"""Build a single-file Supabase Dashboard entrypoint from the tested login handler."""

from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / "supabase/functions/username-login"
OUTPUT = ROOT / "supabase/dashboard/username-login.ts"
IMPORT = "import {createLoginHandler} from './handler.mjs';\n"

entrypoint = (SOURCE / "index.ts").read_text()
if not entrypoint.startswith(IMPORT):
    raise SystemExit("Entrypoint import changed; update this builder before deploying.")

OUTPUT.parent.mkdir(parents=True, exist_ok=True)
OUTPUT.write_text(
    "// Generated by scripts/build-username-login.py; edit the original function files.\n"
    "// Paste this entire file into index.ts in the Supabase Dashboard.\n\n"
    + (SOURCE / "handler.mjs").read_text().rstrip()
    + "\n\n"
    + entrypoint.removeprefix(IMPORT).lstrip()
)
print(OUTPUT)
